BEGIN;
SET LOCAL lock_timeout = '5s';
DO $$ DECLARE n int; cur text; ss text;
BEGIN
  SELECT count(*) INTO n FROM agent_definitions WHERE type='page-rerender' AND is_active
    AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION '741 REFUSED: expected exactly 1 active page-rerender row, found %', n; END IF;
  SELECT default_config #>> '{workflow,start_step}' INTO ss FROM agent_definitions WHERE ...;
  IF ss <> 'check_rerender_mode' THEN RAISE EXCEPTION '741 REFUSED: start_step is %', ss; END IF;
  SELECT default_config #>> '{workflow,steps,check_rerender_mode,config,condition}' INTO cur FROM ...;
  IF cur IS DISTINCT FROM '<the five-value spec.reason clause, verbatim>' THEN
    RAISE EXCEPTION '741 REFUSED: check_rerender_mode.condition is not the clause this migration was generated against. Live: %', cur;
  END IF;
  IF (SELECT default_config #> '{workflow,steps,check_routing_key_known}' FROM ...) IS NOT NULL THEN
    RAISE EXCEPTION '741 REFUSED: check_routing_key_known already exists; do not stack'; END IF;
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname='chk_page_rerender_routing_reason_vocabulary'
               AND conrelid='site_work_items'::regclass) THEN
    RAISE EXCEPTION '741 REFUSED: constraint already exists'; END IF;
  PERFORM snapshot_agent('page-rerender', '741...: pre-flip');
END $$;

-- 1+2: merge the new steps FIRST (see rationale on the nesting trap)
UPDATE agent_definitions SET default_config = jsonb_set(default_config, '{workflow,steps}',
  (default_config #> '{workflow,steps}') || $newsteps$
{"check_routing_key_known": {"action":"conditional", "config": {
    "condition": "<PASTED livespec.CheckRoutingKnownConditionClause()>",
    "then_step":"check_rerender_mode", "else_step":"refuse_unknown_routing_key"}},
 "refuse_unknown_routing_key": {"action":"fail_work_item", "config": {
    "work_item_id":"input_data.work_item_id",
    "status_override":"needs_human_review",
    "error_message":"<PASTED RefuseUnknownRoutingKeyMessageFallback()>",
    "error_message_template":"<PASTED RefuseUnknownRoutingKeyMessageTemplate()>"},
    "next_step":"complete_refused"},
 "complete_refused": {"action":"complete_workflow", "config": {
    "success_message":"Routing key refused - item parked at needs_human_review"}}}
$newsteps$::jsonb), updated_at = now() WHERE type='page-rerender' AND is_active AND ...;

-- 3: transition clause;  4: move start_step;  (separate statements)
UPDATE ... jsonb_set(default_config,'{workflow,steps,check_rerender_mode,config,condition}',
                     to_jsonb($cond$<PASTED TransitionRerenderModeConditionClause()>$cond$::text)) ...;
UPDATE ... jsonb_set(default_config,'{workflow,start_step}','"check_routing_key_known"'::jsonb) ...;

-- 5: THE WRITE DOOR (D3)
ALTER TABLE site_work_items ADD CONSTRAINT chk_page_rerender_routing_reason_vocabulary CHECK (
  item_type <> 'page_rerender' OR spec->>'routing_reason' IS NULL
  OR spec->>'routing_reason' IN ('image_landed','section_data_resolved','cta_links_stale',
                                 'template_changed','literal_markdown')) NOT VALID;

DO $$ DECLARE cfg jsonb; cond text; guard text; n_reason int; n_routing int;
BEGIN
  SELECT default_config #> '{workflow}' INTO cfg FROM agent_definitions WHERE ...;
  IF cfg #>> '{start_step}' <> 'check_routing_key_known' THEN RAISE EXCEPTION '741 VERIFY FAILED: start_step is %', cfg #>> '{start_step}'; END IF;
  FOR guard IN SELECT unnest(ARRAY['check_routing_key_known','refuse_unknown_routing_key','complete_refused',
                                   'check_rerender_mode','render_page','rerender_sections']) LOOP
    IF cfg #> ARRAY['steps', guard] IS NULL THEN RAISE EXCEPTION '741 VERIFY FAILED: step % is missing', guard; END IF;
  END LOOP;
  IF cfg #>> '{steps,refuse_unknown_routing_key,config,status_override}' <> 'needs_human_review' THEN
    RAISE EXCEPTION '741 VERIFY FAILED: the refusal step does not park at needs_human_review (D1)'; END IF;
  IF cfg #>> '{steps,refuse_unknown_routing_key,config,error_message_template}'
       NOT LIKE '%{{.input_data.spec.routing_reason}}%' THEN
    RAISE EXCEPTION '741 VERIFY FAILED: the refusal template does not interpolate the offending key'; END IF;
  guard := cfg #>> '{steps,check_routing_key_known,config,condition}';
  IF guard NOT LIKE '%input_data.spec.routing_reason == null%' THEN
    RAISE EXCEPTION '741 VERIFY FAILED: no `== null` disjunct - every pre-phase-2 item would be refused'; END IF;
  cond := cfg #>> '{steps,check_rerender_mode,config,condition}';
  n_reason  := (length(cond)-length(replace(cond,'input_data.spec.reason ==','')))/length('input_data.spec.reason ==');
  n_routing := (length(cond)-length(replace(cond,'input_data.spec.routing_reason ==','')))/length('input_data.spec.routing_reason ==');
  IF n_reason <> 5 OR n_routing <> 5 THEN
    RAISE EXCEPTION '741 VERIFY FAILED: transition clause carries % reason and % routing tests, expected 5 and 5', n_reason, n_routing; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='chk_page_rerender_routing_reason_vocabulary'
                   AND conrelid='site_work_items'::regclass AND NOT convalidated) THEN
    RAISE EXCEPTION '741 VERIFY FAILED: CHECK absent, or already validated when it should be NOT VALID'; END IF;
END $$;
COMMIT;

// PRE-EXISTING, from phase 1a (commit a3758c399) and bugs_open/404's file, shown so the
// composed message is legible rather than inferred:
//   RoutingReasonSpecKey        == "routing_reason"
//   RerenderSectionReasonNames() == []string{"image_landed", "section_data_resolved",
//                                            "cta_links_stale", "template_changed",
//                                            "literal_markdown"}   // slice ORDER is load-bearing
// so the rendered message ends "...vocabulary (image_landed, section_data_resolved,
// cta_links_stale, template_changed, literal_markdown). ..."
func RefuseUnknownRoutingKeyMessageTemplate() string {
  return "This page_rerender item was REFUSED, not assembled: its spec." +
    RoutingReasonSpecKey + " = '{{.input_data.spec." + RoutingReasonSpecKey +
    "}}' is not in the sections-rerender vocabulary (" +
    strings.Join(RerenderSectionReasonNames(), ", ") +
    "). Before this refusal existed, an unrecognised routing key completed GREEN having changed " +
    "nothing - bugs_open/440. If the value was meant as a note for a human, move it to spec.reason, " +
    "which is free prose and is never validated. If it was meant to ROUTE, use a vocabulary value, or " +
    "add one to RerenderSectionReasons in platform/livespec and paste the regenerated gate clause and " +
    "this message into a migration. RFC_062."
}

func RefuseUnknownRoutingKeyMessageFallback() string {
  // Same, minus the {{...}}: names the FIELD and the vocabulary, and tells the reader the
  // offending value is one field away on the row they are already looking at.
  return "... its spec." + RoutingReasonSpecKey + " is not in the sections-rerender vocabulary (" +
    strings.Join(RerenderSectionReasonNames(), ", ") + "). Read the offending value at spec." +
    RoutingReasonSpecKey + " on this row. ..."
}

// The blocker discharged BY EXECUTION (was already in the tree for this round):
func CheckRoutingKnownConditionClause() string {
  parts := make([]string, 0, len(RerenderSectionReasons)+2)
  parts = append(parts, "input_data.spec."+RoutingReasonSpecKey+" == null") // <- LOAD-BEARING
  parts = append(parts, "input_data.spec."+RoutingReasonSpecKey+" == ''")
  for _, r := range RerenderSectionReasons {
    parts = append(parts, "input_data.spec."+RoutingReasonSpecKey+" == '"+r.Name+"'")
  }
  return strings.Join(parts, " OR ")
}

const failWorkItemNoValue = "<no value>"

func renderFailWorkItemMessage(tmplText string, collectedData map[string]interface{}) (string, error) {
  tmpl, err := template.New("fail_work_item_error_message").
    Option("missingkey=error").Parse(tmplText)
  if err != nil { return "", fmt.Errorf("error_message_template does not parse: %w", err) }
  var out strings.Builder
  if err := tmpl.Execute(&out, collectedData); err != nil {
    return "", fmt.Errorf("error_message_template failed to render: %w", err) }
  rendered := out.String()
  if strings.Contains(rendered, failWorkItemNoValue) {
    return "", fmt.Errorf("error_message_template rendered %q - a key it names is present but nil, "+
      "so the message would report the wrong thing to whoever reads the parked item; "+
      "rendered text was: %s", failWorkItemNoValue, rendered) }
  if strings.TrimSpace(rendered) == "" {
    return "", fmt.Errorf("error_message_template rendered empty text") }
  return rendered, nil
}

