const failWorkItemTemplateFallbackCode = "FAIL_WORK_ITEM_MESSAGE_TEMPLATE_FALLBACK"

func specWith(routingReason interface{}) map[string]interface{} {   // ALWAYS sets the key, nil included
  return collectedWithSpec(map[string]interface{}{"page_name": "about", "routing_reason": routingReason})
}
func specWithoutRoutingKey() map[string]interface{} {               // the legacy population's shape
  return collectedWithSpec(map[string]interface{}{"page_name": "about"})
}
func collectedWithSpec(spec map[string]interface{}) map[string]interface{} {
  return map[string]interface{}{"input_data": map[string]interface{}{
    "spec": spec, "work_item_id": "11111111-1111-1111-1111-111111111111"}}
}

func TestRefusalMessageNamesTheBadKeyAndTheVocabulary(t *testing.T) {
  const badKey = "tool_retirement"   // a real one: 16 live items, bugs_open/440
  got, err := renderFailWorkItemMessage(livespec.RefuseUnknownRoutingKeyMessageTemplate(), specWith(badKey))
  if err != nil { t.Fatalf("must render for the state that reaches it: %v", err) }
  if !strings.Contains(got, badKey) { t.Errorf("D1 requires the BAD KEY named. Rendered: %s", got) }
  for _, name := range livespec.RerenderSectionReasonNames() {
    if !strings.Contains(got, name) { t.Errorf("D1 requires the VOCABULARY; %q missing", name) } }
  if strings.Contains(got, "{{") { t.Errorf("template shipped un-rendered: %s", got) }
  if fb := livespec.RefuseUnknownRoutingKeyMessageFallback(); strings.TrimSpace(fb) == "" {
    t.Error("the static fallback is empty; a failed render would park the item mute") }
}

func TestRenderFailWorkItemMessage_LoudOnPresentButNilKey(t *testing.T) {
  _, err := renderFailWorkItemMessage(livespec.RefuseUnknownRoutingKeyMessageTemplate(), specWith(nil))
  if err == nil { t.Fatal("present-but-nil rendered without complaint") }
  if !strings.Contains(err.Error(), "<no value>") { t.Errorf("error must name what it saw: %v", err) }
  // the ABSENT case is a DIFFERENT mechanism and must also be loud
  _, err = renderFailWorkItemMessage(livespec.RefuseUnknownRoutingKeyMessageTemplate(), specWithoutRoutingKey())
  if err == nil { t.Fatal("absent routing_reason rendered without complaint") }
  if strings.Contains(err.Error(), "<no value>") {
    t.Errorf("absent must be caught by missingkey=error, not the guard - missingkey is no longer set: %v", err) }
}

// TestRenderFailWorkItemMessage_LoudOnMissingAndMalformed: table of {does not parse,
// names a path that is not there, renders empty} - each must return a non-nil error.

func TestFailWorkItemConfigKeysCoverTheKeysItActuallyReads(t *testing.T) {
  liveShape := map[string]interface{}{"work_item_id": "input_data.work_item_id",
    "error_message": "Content validation failed - needs human review",
    "status_override": "needs_human_review"}   // the shape MEASURED on 6 agents
  unknown, checked := datahelpers.UnknownConfigKeys("fail_work_item", liveShape)
  if !checked { t.Fatal("detector is OFF (checked=false) - an empty result from an unarmed detector is not a pass") }
  if len(unknown) != 0 { t.Errorf("detector calls %v unknown, but fail_work_item reads them straight from StepConfig.Config", unknown) }
  withTemplate := map[string]interface{}{... , "error_message_template": livespec.RefuseUnknownRoutingKeyMessageTemplate()}
  if unknown, _ := datahelpers.UnknownConfigKeys("fail_work_item", withTemplate); len(unknown) != 0 {
    t.Errorf("phase 3's own refusal step carries unrecognised keys %v", unknown) }
  bogus := map[string]interface{}{"work_item_id": "input_data.work_item_id",
    "error_messsage": "typo, three s's", "no_such_settingx": true}   // NEGATIVE CONTROL
  unknown, checked = datahelpers.UnknownConfigKeys("fail_work_item", bogus)
  if !checked { t.Fatal("negative control: detector unarmed") }
  if len(unknown) != 2 { t.Errorf("negative control: expected both bogus keys reported, got %v", unknown) }
}

// Pins the RFC_022 ENUMERATION QUERY itself, because go test has no database: the thing a
// reviewer needs in order to RE-CHECK condition 3, which 2026-07-29 §1 says must be
// enumerated rather than asserted. [MEASURED 2026-09-03] it returned 7 / 6 / 0.
func TestErrorMessageTemplateIsAbsentFromEveryLiveStep(t *testing.T) {
  const enumeration = `SELECT count(*) FILTER (WHERE s.value->'config' ? 'error_message_template') ` +
    `FROM agent_definitions a, jsonb_each(a.default_config->'workflow'->'steps') s ` +
    `WHERE a.is_active AND COALESCE(a.is_snapshot,false)=false AND a.deleted_at IS NULL ` +
    `AND s.value->>'action'='fail_work_item'`
  if !strings.Contains(enumeration, "error_message_template") {
    t.Fatal("the enumeration no longer names the key it is supposed to count") }
  if !strings.Contains(enumeration, "is_snapshot") {
    t.Error("a fleet enumeration that does not exclude snapshots counts dead rows, and " +
      "would report live consumers that are not live") }
}
